function debounce(fn, delay) {
  let timer;
  return (...args) => {
    timer = setTimeout(() => fn(...args), delay);
  };
}

const log = debounce((q) => console.log('search', q), 100);
log('a');
log('ab');
log('abc');
// Expected: only "search abc"

