function memoize(fn) {
  const cache = {};
  return (...args) => {
    const key = args[0];
    if (key in cache) return cache[key];
    return (cache[key] = fn(...args));
  };
}

const add = memoize((a, b) => a + b);
console.log(add(1, 2), add(1, 5));

